  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Boolean;
    in attribute io_3 : Real;
    in attribute io_4 : Boolean;
    attribute modeIsManual : Boolean := false;
    attribute previousPressed : Boolean := false;
    perform action tick {
      first start;
      then if io_1 and not previousPressed {
        first start;
        then assign modeIsManual := (not modeIsManual);
      }
      then assign previousPressed := io_1;
    }
    out attribute io_2 : Integer = (if not modeIsManual and io_4 and io_3 <= 15.0 ? 1000 else (if modeIsManual and io_4 and io_3 <= RealFunctions::floor(io_0) ? 1000 else 0));
    out attribute io_5 : Integer = (if modeIsManual ? RealFunctions::floor(io_0) else 15);
  }
  part system : Controller;
}
